    """Merge two sorted lists into one sorted list (duplicates are kept)."""
    i, j = 0, 0
    result = []

    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1

    # Append remaining elements from the first list
    while i < len(a):
        result.append(a[i])
        i += 1

    # Append remaining elements from the second list
    while j < len(b):
        result.append(b[j])
        j += 1

