def flatten(nested: list) -> list:
    """Return all integers in nested (a list of ints and lists, at any depth) in one list."""
    if not nested:
        return []

    flat_list = []
    for item in nested:
        if isinstance(item, list):
            flat_list.extend(flatten(item))
        else:
            flat_list.append(item)
    return flat_list

