def binary_search(nums: list[int], target: int) -> int:
    """Return the index of target in the sorted list nums, or -1 if it is not there."""
    if not nums:
        return -1  # Return -1 for empty list

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2  # Calculate the middle index

        if nums[mid] == target:
            return mid  # Return the index if it matches the target
        elif nums[mid] < target:
            left = mid + 1  # Shift left to find a larger number
        else:
            right = mid - 1  # Shift right to find a smaller number

    return -1  # Return -1 if the target is not found
