import string

def valid_parentheses(s: str) -> bool:
    # Dictionary to map opening brackets to their corresponding closing brackets
    bracket_map = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    # Stack to keep track of opening brackets
    stack = []

    # Iterate over each character in the string
    for char in s:
        # If the character is an opening bracket, push it onto the stack
        if char in bracket_map:
            stack.append(char)
        else:
            # If the character is a closing bracket
            if not stack:
                return False  # No matching opening bracket
            # Check if the closing bracket matches the top of the stack
            if bracket_map[char] != stack.pop():
                return False  # No matching opening bracket

    # If the stack is empty, all brackets were matched correctly
    return len(stack) == 0

def valid_parentheses(s: str) -> bool:
    # Initialize a stack to keep track of opening brackets
    stack = []

    # Iterate over each character in the string
    for char in s:
        if char == '(':
            # If the stack is empty, push the opening bracket onto the stack
            stack.append(char)
        elif char == ')':
            # If the stack is not empty, check if the top element is an opening bracket
            if stack and stack[-1] == '(':
                # Pop the opening bracket from the stack
                stack.pop()
            else:
                # If the stack is empty or the top element is not an opening bracket, return False
                return False

    # If the stack is empty, all brackets were properly matched and nested
    return len(stack) == 0

